import numpy as np


def r(x):
    # Project the input onto the valid domain [0, 1] using clipping.
    # For any x in [0, 1], this is a identity conservation transform.
    return float(np.clip(x, 0.0, 1.0))


def R(y_orig, y_new):
    # The output probability must be conserved.
    return bool(np.isclose(y_orig, y_new, rtol=1e-12, atol=1e-12))
